  teaching: [
    { id: "TEACH-2026-0005", category: "course", year: 2026, en: "<h3>📊 Biostatistics</h3><strong>Objective:</strong> Apply concepts and techniques in probability, descriptive statistics, sampling, estimation, and regression to analyze data in agricultural and animal sciences, using statistical computing tools to support data interpretation and evidence generation.", es: "<h3>📊 Bioestadística</h3><strong>Objetivo:</strong> Utilizar conceptos y técnicas de probabilidad, estadística descriptiva, muestreo, estimación y regresión para el análisis de datos en ciencias agropecuarias, apoyándose en herramientas estadísticas computacionales para la interpretación de información y la generación de evidencia." },
    { id: "TEACH-2026-0002", category: "course", year: 2026, en: "<h3>☣️ Animal Hygiene</h3><strong>Objective:</strong> Identify and analyze risk factors associated with diseases, zoonoses, and other health hazards in animal production systems, integrating principles of prevention, biosecurity, food safety, and animal health within the applicable regulatory framework.", es: "<h3>☣️ Higiene Pecuaria</h3><strong>Objetivo:</strong> Identificar y analizar factores de riesgo asociados con enfermedades, zoonosis y otros peligros sanitarios en los sistemas de producción animal, integrando principios de prevención, bioseguridad, inocuidad y sanidad animal dentro del marco normativo correspondiente." },
    { id: "TEACH-2026-0004", category: "course", year: 2026, en: "<h3>🔬 Research Fundamentals</h3><strong>Objective:</strong> Apply research principles and methodological tools for searching, analyzing, and critically integrating scientific information and for developing academic writing within the professional field.", es: "<h3>🔬 Fundamentos de la Investigación</h3><strong>Objetivo:</strong> Aplicar fundamentos y herramientas metodológicas de investigación para la búsqueda, análisis e integración crítica de información científica y el desarrollo de escritura académica en el área de formación profesional." },
    { id: "TEACH-2026-0003", category: "course", year: 2026, en: "<h3>📝 Graduation Seminar</h3><strong>Objective:</strong> Design and structure an undergraduate degree project in agricultural and animal sciences by integrating the research problem, objectives, and methodological strategy according to scientific and feasibility criteria.", es: "<h3>📝 Seminario de Titulación</h3><strong>Objetivo:</strong> Diseñar y estructurar un trabajo de titulación en ciencias agropecuarias, articulando el planteamiento del problema, los objetivos y la estrategia metodológica bajo criterios científicos y de viabilidad." },
    { id: "TEACH-2026-0006", category: "course", year: 2026, en: "<h3>🔄 Livestock Production Systems</h3><strong>Objective:</strong> Analyze the organization and functioning of major livestock production systems through their resources, inputs, processes, and outputs, integrating production and management criteria.", es: "<h3>🔄 Sistemas de producción pecuaria</h3><strong>Objetivo:</strong> Analizar la organización y funcionamiento de los principales sistemas de producción pecuaria a partir de sus recursos, entradas, procesos y salidas, integrando criterios productivos y de manejo." },
    { id: "TEACH-2026-0007", category: "course", year: 2026, en: "<h3>♻️ Agricultural and Livestock Waste Management</h3><strong>Objective:</strong> Identify, characterize, and propose management and utilization alternatives for agricultural and livestock waste, integrating principles of waste management, biomass valorization, and environmental impact reduction.", es: "<h3>♻️ Manejo de residuos agropecuarios</h3><strong>Objetivo:</strong> Identificar, caracterizar y proponer alternativas de manejo y aprovechamiento de residuos agropecuarios, integrando principios de gestión, valorización de biomasa y reducción de impactos ambientales." }
  ],
